-- ============================================================
-- CAG V2 Detailed Per-Record Experiment Results
-- Source: original reproducible package CAG_V2_可复现实验包.zip
-- Script: run_cag_v2_experiments.py
-- Fixed seed: 20260908
--
-- This SQL contains actual reconstructed V2 per-record data:
--   295 material-cell Gold records
--   177 structured constraint Gold tuples
--   293 fixed-seed controlled candidate records with stage decisions
--   120 dedicated repair cases with prediction and correctness
--   per-candidate records for all 10 stability seeds
--   per-seed stage summaries
--
-- IMPORTANT: these are the reconstructed CAG V2 supplementary experiments.
-- They are NOT the unavailable per-tuple records of the older 1,894-tuple main experiment.
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS cag_v2_extraction_record;
DROP TABLE IF EXISTS cag_v2_structured_gold;
DROP TABLE IF EXISTS cag_v2_fixed_candidate_record;
DROP TABLE IF EXISTS cag_v2_repair_case;
DROP TABLE IF EXISTS cag_v2_stability_candidate_record;
DROP TABLE IF EXISTS cag_v2_stability_run_summary;
DROP TABLE IF EXISTS cag_v2_metadata;

CREATE TABLE cag_v2_metadata (
  id INT PRIMARY KEY AUTO_INCREMENT,
  item_name VARCHAR(128) NOT NULL,
  item_value VARCHAR(1000) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE cag_v2_extraction_record (
  record_id INT PRIMARY KEY,
  equipment VARCHAR(64) NOT NULL,
  component VARCHAR(128) NOT NULL,
  material VARCHAR(255) NOT NULL,
  selected_strict_rule TINYINT(1) NOT NULL,
  selected_dictionary_rag TINYINT(1) NOT NULL,
  selected_maximum_recall TINYINT(1) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE cag_v2_structured_gold (
  record_id INT PRIMARY KEY,
  equipment VARCHAR(64) NOT NULL,
  component VARCHAR(128) NOT NULL,
  material_type VARCHAR(64) NOT NULL,
  material_grade VARCHAR(128) NOT NULL,
  material_standard VARCHAR(128) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE cag_v2_fixed_candidate_record (
  candidate_id INT PRIMARY KEY,
  seed INT NOT NULL,
  source_structured_id INT NOT NULL,
  equipment VARCHAR(64) NOT NULL,
  component VARCHAR(128) NOT NULL,
  material_type VARCHAR(64) NOT NULL,
  material_grade VARCHAR(128) NOT NULL,
  material_standard VARCHAR(128) NULL,
  candidate_tag VARCHAR(64) NOT NULL,
  domain_pass TINYINT(1) NOT NULL,
  fd_pass TINYINT(1) NOT NULL,
  business_pass TINYINT(1) NOT NULL,
  business_stage_output TINYINT(1) NOT NULL,
  repair_applied TINYINT(1) NOT NULL,
  final_standard VARCHAR(128) NULL,
  final_output TINYINT(1) NOT NULL,
  initial_exact_gold TINYINT(1) NOT NULL,
  final_exact_gold TINYINT(1) NOT NULL,
  FOREIGN KEY (source_structured_id) REFERENCES cag_v2_structured_gold(record_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE cag_v2_repair_case (
  repair_id INT PRIMARY KEY,
  case_type VARCHAR(64) NOT NULL,
  source_structured_id INT NOT NULL,
  equipment VARCHAR(64) NOT NULL,
  component VARCHAR(128) NOT NULL,
  gold_type VARCHAR(64) NOT NULL,
  gold_grade VARCHAR(128) NOT NULL,
  gold_standard VARCHAR(128) NOT NULL,
  corrupted_type VARCHAR(64) NULL,
  corrupted_grade VARCHAR(128) NULL,
  corrupted_standard VARCHAR(128) NULL,
  candidate_options TEXT NULL,
  predicted_type VARCHAR(64) NULL,
  predicted_grade VARCHAR(128) NULL,
  predicted_standard VARCHAR(128) NULL,
  is_correct TINYINT(1) NOT NULL,
  FOREIGN KEY (source_structured_id) REFERENCES cag_v2_structured_gold(record_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE cag_v2_stability_candidate_record (
  row_id BIGINT PRIMARY KEY AUTO_INCREMENT,
  seed INT NOT NULL,
  candidate_id_within_seed INT NOT NULL,
  source_structured_id INT NOT NULL,
  equipment VARCHAR(64) NOT NULL,
  component VARCHAR(128) NOT NULL,
  material_type VARCHAR(64) NOT NULL,
  material_grade VARCHAR(128) NOT NULL,
  material_standard VARCHAR(128) NULL,
  candidate_tag VARCHAR(64) NOT NULL,
  domain_pass TINYINT(1) NOT NULL,
  fd_pass TINYINT(1) NOT NULL,
  business_pass TINYINT(1) NOT NULL,
  business_stage_output TINYINT(1) NOT NULL,
  repair_applied TINYINT(1) NOT NULL,
  final_standard VARCHAR(128) NULL,
  final_output TINYINT(1) NOT NULL,
  initial_exact_gold TINYINT(1) NOT NULL,
  final_exact_gold TINYINT(1) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE cag_v2_stability_run_summary (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  seed INT NOT NULL,
  stage VARCHAR(64) NOT NULL,
  gold_count INT NOT NULL,
  generated_count INT NOT NULL,
  exact_match_count INT NOT NULL,
  missing_count INT NOT NULL,
  redundant_count INT NOT NULL,
  precision_value DECIMAL(12,8) NOT NULL,
  recall_value DECIMAL(12,8) NOT NULL,
  f1_value DECIMAL(12,8) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

