SET FOREIGN_KEY_CHECKS=1;

-- Verification queries
SELECT COUNT(*) AS extraction_records FROM cag_v2_extraction_record;       -- 295
SELECT COUNT(*) AS structured_gold_records FROM cag_v2_structured_gold;    -- 177
SELECT COUNT(*) AS fixed_candidates FROM cag_v2_fixed_candidate_record;    -- 293
SELECT COUNT(*) AS repair_cases FROM cag_v2_repair_case;                   -- 120
SELECT SUM(is_correct) AS repair_correct FROM cag_v2_repair_case;          -- 114

SELECT
  SUM(selected_strict_rule) AS strict_rule_count,
  SUM(selected_dictionary_rag) AS dictionary_rag_count,
  SUM(selected_maximum_recall) AS maximum_recall_count
FROM cag_v2_extraction_record;

SELECT candidate_tag, COUNT(*) AS n
FROM cag_v2_fixed_candidate_record
GROUP BY candidate_tag
ORDER BY candidate_tag;
